'use strict';
const E=ShelterEngine,KEY='last-light-v2',OLD_KEY='last-light-v1',$=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.floor(n).toLocaleString('zh-CN'),signed=n=>(n>=0?'+':'−')+Math.abs(n).toFixed(1),timer=s=>`${Math.floor(Math.max(0,s)/60)}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,'0')}`;
let state,selected=2,riding=null,toastHandle,modalKind='',buildFilter='all',saveFailed=false,wardrobePerson=null;
let recovered=false,migrated=false;try{const raw=localStorage.getItem(KEY);if(raw){state=JSON.parse(raw);if(!E.validate(state))throw Error('invalid');}else{const old=localStorage.getItem(OLD_KEY);state=old?E.migrate(JSON.parse(old)):E.fresh();migrated=!!old;if(!E.validate(state))state=E.fresh();}}catch{state=E.fresh();recovered=true;}
if(!state.floors.some(f=>f.id===selected))selected=state.floors[0].id;
const initialSettlement=E.settle(state);const justCompleted=new Set(state.floors.filter(f=>f.readyAt<=Date.now()).map(f=>f.id));
function character(p,extra=''){const h=CHARACTER_ANCHORS.heads[p.look.head],t=CHARACTER_ANCHORS.tops[p.look.top],left=13+74*t.x-91*h.x,top=45+34*t.y+2-50*h.y;return `<span class="character ${extra}" aria-hidden="true"><img class="part-bottom" src="${asset('assets/people/bottoms-'+p.look.bottom+'.png')}" alt=""><img class="part-top" src="${asset('assets/people/tops-'+p.look.top+'.png')}" alt=""><img class="part-head" style="left:${left.toFixed(3)}%;top:${top.toFixed(3)}%" src="${asset('assets/people/heads-'+p.look.head+'.png')}" alt=""></span>`;}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveFailed=false;}catch{saveFailed=true;$('saveStatus').textContent='保存失败，请在 ⚙ 中导出存档';}}
function header(){const now=Date.now(),rate=E.net(state,now);$('coins').textContent=fmt(state.coins);$('netRate').textContent=signed(rate)+' / 分钟';$('netRate').classList.toggle('negative',rate<0);$('roomCount').textContent=state.floors.filter(f=>f.readyAt<=now).length;$('peopleCount').textContent=state.people.length;$('bedsCount').textContent=E.beds(state);$('floorCaption').textContent=`${state.floors.length} 层 · 第 ${Math.floor((now-state.createdAt)/86400000)+1} 天`;}
function renderFloors(){const now=Date.now();$('floors').innerHTML=state.floors.map(f=>{const t=ROOMS[f.type],c=CATEGORIES[t.category],ps=E.assigned(state,f),presence=E.present(state,f,now),shown=[...ps.map(p=>({person:p,guest:false})),...presence.guests.map(v=>({person:v.person,guest:true}))],building=f.readyAt>now;return `<div class="floor" id="floor-${f.id}"><div class="floor-label">B${String(f.level).padStart(2,'0')}${presence.overflow.length?`<div class="landing-guest" title="${esc(presence.overflow[0].person.name)} 正在候场">${character(presence.overflow[0].person)}<small>候场 ${presence.overflow.length} 人</small></div>`:''}</div><button class="shaft ${riding&&state.visitors.find(v=>v.id===riding)?.destination===f.id?'target':''}" data-lift="${f.id}" aria-label="电梯前往 B${f.level}"><span class="lift-number">${state.lift===f.id?'●':'↓'}</span>${state.lift===f.id?`<div class="lift-cabin">${riding?character(state.visitors.find(v=>v.id===riding)):''}</div>`:''}</button><div class="room ${selected===f.id?'selected':''} ${building?'building':''} ${!f.enabled?'paused':''}" role="button" tabindex="0" data-room="${f.id}" aria-label="管理 B${f.level} ${esc(f.name)}" style="--cat:${c.color};--cat-dark:${c.dark}"><img class="room-art" src="${asset('assets/rooms/'+f.type+'.webp')}" alt="${esc(t.name)}房间背景"><div class="room-people">${building?'':shown.map((v,i)=>`<div style="left:${10+i*70/Math.max(shown.length,1)}%;animation-delay:-${i*.7}s" class="character ${v.guest?'visiting':''}" title="${esc(v.person.name)}${v.guest?' · 临时访客':''}">${character(v.person).replace(/^<span[^>]*>|<\/span>$/g,'')}${v.guest?'<small class="guest-label">访客</small>':''}</div>`).join('')}</div><span class="room-badge" id="badge-${f.id}">${building?'建造中':!f.enabled?'已暂停':ps.length+' / '+f.capacity+' 人'}</span>${building?`<div class="construction"><span>正在建造 · ${esc(f.name)}</span><strong id="timer-${f.id}">${timer((f.readyAt-now)/1000)}</strong><div class="construction-progress"><i id="progress-${f.id}"></i></div><span>完成后可安排居民</span></div>`:''}<div class="room-strip"><strong>B${String(f.level).padStart(2,'0')} · ${esc(f.name)}</strong><span id="rate-${f.id}">${building?'施工中':signed(E.roomRate(state,f).net)+' 币/分'}</span></div></div></div>`;}).join('');const v=state.visitors.find(v=>v.id===riding);$('rideStatus').textContent=v?`${v.name} 想去 B${v.destination} · 点击目标层电梯`:'接送访客获得 25 金币 · 有空床位时可入住';$('surfacePeople').innerHTML=state.visitors.filter(v=>v.id!==riding).slice(0,4).map(p=>character(p)).join('');updateTimers();}
function renderDetails(){const f=state.floors.find(f=>f.id===selected),t=ROOMS[f.type],c=CATEGORIES[t.category],ps=E.assigned(state,f),building=f.readyAt>Date.now();$('details').innerHTML=`<section class="card"><div class="detail-header" style="--cat:${c.color};--cat-dark:${c.dark}"><img class="mini-art" src="${asset('assets/rooms/'+f.type+'.webp')}" alt=""><small>B${String(f.level).padStart(2,'0')} · ${c.name}类楼层</small><h2>${esc(f.name)}</h2><p>${esc(t.description)}</p></div><div class="detail-stats"><div class="stat"><span>所在层数</span><strong>地下 ${f.level} 层</strong></div><div class="stat"><span>最大容纳人数</span><strong>${ps.length} / ${f.capacity} 人</strong></div><div class="stat"><span>基础产出（满员）</span><strong>+${f.income} 金币 / 分钟</strong></div><div class="stat"><span>运行消耗</span><strong>−${f.expense} 金币 / 分钟</strong></div><div class="stat"><span>标准建造金额</span><strong>${t.cost} 金币</strong></div><div class="stat"><span>建造所需时间</span><strong>${t.seconds===0?'立即建成':timer(t.seconds)}</strong></div><div class="stat stat-separator"><span>当前实际收入</span><strong id="detailIncome">—</strong></div><div class="stat"><span>当前实际消耗</span><strong id="detailExpense">—</strong></div><div class="stat"><span>当前净收入</span><strong id="detailNet">—</strong></div></div><div id="cashWarning"></div><div class="worker-tags">${ps.length?ps.map(p=>`<span class="worker-tag">${p.specialty===t.category?'★ ':''}${esc(p.name)}</span>`).join(''):'<span class="empty">暂无居民在这一层</span>'}</div>${building?`<button class="primary" disabled id="detailBuildTimer">建造中 · ${timer((f.readyAt-Date.now())/1000)}</button>`:`<button class="primary" id="assignRoom">安排居民 · ${ps.length} / ${f.capacity}</button><button class="secondary" id="toggleRoom">${f.enabled?'暂停运行（停止收益与消耗）':'恢复运行'}</button>`}<button class="secondary" id="renameRoom">修改楼层名称</button><p class="note">每位居民贡献满员基础产出的 1/${f.capacity}；特长匹配额外增加 25%。维护费按整层计算，暂停后不计收支。${f.type==='dorm'?'<br>宿舍提供社区床位，安排在宿舍的居民处于休息状态。':''}</p></section>`;updateDetailRates();}
function updateDetailRates(){const f=state.floors.find(f=>f.id===selected),r=E.roomRate(state,f);if(!$('detailIncome'))return;$('detailIncome').textContent='+'+r.income.toFixed(1)+' 金币 / 分钟';$('detailExpense').textContent='−'+r.expense.toFixed(1)+' 金币 / 分钟';$('detailNet').textContent=signed(r.net)+' 金币 / 分钟';$('detailNet').className=r.net<0?'negative':'positive';$('cashWarning').innerHTML=state.coins<1&&E.net(state)<0?'<div class="cash-warning">金币已见底。安排闲置居民或暂停亏损楼层可恢复收益。</div>':'';}
function personRow(p,visitor=false){const f=state.floors.find(f=>f.id===p.floor);return `<div class="person-row"><div class="portrait">${character(p)}</div><div class="person-info"><strong>${esc(p.name)} <span style="color:#9b9f92;font-size:9px;font-weight:400">${p.age} 岁</span></strong><small>特长：${SPECIALTIES[p.specialty][0]}</small><small>${visitor?'想去 B'+p.destination+' · '+esc(state.floors.find(f=>f.id===p.destination).name):f?'B'+f.level+' · '+esc(f.name):'待安排 · 可分配工作'}</small></div><button ${visitor?'data-ride':'data-person'}="${p.id}">${visitor?p.id===riding?'已接到':'接送':'详情'}</button></div>`;}
function renderPeople(){$('waitingCount').textContent=state.visitors.length+' 人';$('visitors').innerHTML=state.visitors.length?state.visitors.map(p=>personRow(p,true)).join(''):'<p class="empty">暂时没有访客。电台每 45 秒<br>最多接待一位新朋友。</p>';$('residents').innerHTML=`<div class="person-list">${state.people.slice(0,8).map(p=>personRow(p)).join('')}</div><p class="note">社区床位 ${state.people.length} / ${E.beds(state)} · 另建宿舍可接纳更多居民</p>`;}
const TASKS=[{id:'staff',name:'让社区运转起来',desc:'安排 4 位居民 · 奖励 80 币',reward:80,test:()=>state.people.filter(p=>p.floor!==null).length>=4},{id:'build',name:'开拓第四层',desc:'建成第 4 层 · 奖励 100 币',reward:100,test:()=>state.floors.filter(f=>f.readyAt<=Date.now()).length>=4},{id:'earn',name:'第一笔社区收入',desc:'累计净赚 100 币 · 奖励 60 币',reward:60,test:()=>state.earned>=100},{id:'family',name:'热闹起来的新家',desc:'接纳 6 位居民 · 奖励 120 币',reward:120,test:()=>state.people.length>=6}];
function tasks(){let changed=false;for(const t of TASKS)if(!state.claimed.includes(t.id)&&t.test()){state.claimed.push(t.id);state.coins+=t.reward;E.log(state,`完成「${t.name}」，获得 ${t.reward} 金币。`);toast(`任务完成：${t.name} · +${t.reward} 金币`);changed=true;}return changed;}
function renderSidebar(){$('categoryList').innerHTML=Object.values(CATEGORIES).map(c=>`<div class="cat-row"><span class="cat-dot" style="background:${c.color}"></span><div><strong>${c.name}</strong><small>${c.desc}</small></div></div>`).join('');$('tasks').innerHTML=TASKS.map(t=>`<div class="task ${state.claimed.includes(t.id)?'done':''}"><span class="circle">${state.claimed.includes(t.id)?'✓':''}</span><div><strong>${t.name}</strong><small>${state.claimed.includes(t.id)?'已完成 · 奖励已到账':t.desc}</small></div></div>`).join('');$('taskCount').textContent=state.claimed.length+' / 4';$('logs').innerHTML=state.logs.slice(0,4).map(l=>`<div class="log"><time>${new Date(l.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time>${esc(l.text)}</div>`).join('');}
function renderAll(){header();renderFloors();renderDetails();renderPeople();renderSidebar();}
function updateTimers(){const now=Date.now();for(const f of state.floors){if($('timer-'+f.id))$('timer-'+f.id).textContent=timer((f.readyAt-now)/1000);if($('progress-'+f.id))$('progress-'+f.id).style.width=Math.max(0,Math.min(100,100*(now-f.startedAt)/(f.readyAt-f.startedAt)))+'%';if($('rate-'+f.id))$('rate-'+f.id).textContent=f.readyAt>now?'施工中':signed(E.roomRate(state,f,now).net)+' 币/分';}const f=state.floors.find(f=>f.id===selected);if($('detailBuildTimer'))$('detailBuildTimer').textContent='建造中 · '+timer((f.readyAt-now)/1000);}
function showModal(title,html,kind=''){modalKind=kind;$('dialogBody').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button id="closeModal" aria-label="关闭">×</button></div>${html}`;if(!$('dialog').open)$('dialog').showModal();}
function closeModal(){$('dialog').close();modalKind='';}
function buildModal(filter=buildFilter){buildFilter=filter;showModal('开拓新的一层',`<p class="empty">下一层为 B${state.floors.length+1} · 当前持有 ${fmt(state.coins)} 金币</p><div class="tabs"><button data-category="all" class="${filter==='all'?'active':''}">全部</button>${Object.entries(CATEGORIES).map(([k,c])=>`<button data-category="${k}" class="${filter===k?'active':''}">${c.name}</button>`).join('')}</div><div class="build-grid">${Object.entries(ROOMS).filter(([,t])=>filter==='all'||t.category===filter).map(([k,t])=>{const c=CATEGORIES[t.category];return `<article class="build-card" style="--cat:${c.color};--cat-dark:${c.dark}"><img src="${asset('assets/rooms/'+k+'.webp')}" alt="${t.name}"><div class="category-strip"><strong>${t.name}</strong><span>${t.capacity} 人</span></div><div class="build-info"><div class="build-specs"><span>产出 <strong>+${t.income}/分</strong></span><span>消耗 <strong>−${t.expense}/分</strong></span><span>建造 <strong>${t.seconds?timer(t.seconds):'即时'}</strong></span></div><button data-build="${k}" ${state.coins<t.cost||state.floors.length>=30?'disabled':''}>建造 · ${t.cost} 金币</button></div></article>`;}).join('')}</div><p class="note">产出为满员、无特长加成时的基础收入。建造期间不产生收支。最多 30 层，可重复建造同一种房间。</p>`,'build');}
function assignModal(id=null){const now=Date.now();if(id!==null){const p=state.people.find(p=>p.id===id);showModal('为 '+esc(p.name)+' 安排楼层',`<p class="empty">${p.age} 岁 · 特长：${SPECIALTIES[p.specialty][0]}。★ 表示匹配特长。</p>${state.floors.map(f=>{const ps=E.assigned(state,f),match=p.specialty===ROOMS[f.type].category;return `<div class="assign-row"><span class="cat-dot" style="background:${CATEGORIES[ROOMS[f.type].category].color}"></span><div class="info"><strong>B${f.level} · ${esc(f.name)} ${match?'★':''}</strong><small>${ps.length} / ${f.capacity} 人 · ${f.readyAt>now?'正在建造':!f.enabled?'暂停运行':signed(E.roomRate(state,f).net)+' 金币/分'}</small></div><button data-assign="${p.id}:${f.id}" ${f.readyAt>now||ps.length>=f.capacity&&p.floor!==f.id?'disabled':''}>${p.floor===f.id?'当前楼层':'安排'}</button></div>`;}).join('')}<button class="secondary" data-assign="${p.id}:0">设为待安排</button>`,'assign');}else{const f=state.floors.find(f=>f.id===selected),ps=E.assigned(state,f);showModal('B'+f.level+' · '+esc(f.name)+' 的居民',`<p class="empty">${ps.length} / ${f.capacity} 人 · ★ 匹配的居民增加 25% 个人收入。可从其他楼层调入。</p>${state.people.map(p=>`<div class="assign-row"><div class="portrait">${character(p)}</div><div class="info"><strong>${esc(p.name)} · ${p.age} 岁 ${p.specialty===ROOMS[f.type].category?'★':''}</strong><small>${SPECIALTIES[p.specialty][0]} · ${p.floor===null?'待安排':'当前 B'+p.floor}</small></div><button data-assign="${p.id}:${p.floor===f.id?0:f.id}" ${p.floor!==f.id&&ps.length>=f.capacity?'disabled':''}>${p.floor===f.id?'调出':'安排'}</button></div>`).join('')}`,'assign');}}
function directory(){showModal('社区居民册',`<p class="empty">${state.people.length} 位居民 · 床位 ${E.beds(state)} · 点击详情可改名字、换装或分配工作。</p><div class="directory-grid">${state.people.map(p=>`<div class="directory-card"><div class="portrait">${character(p)}</div><div class="person-info"><strong>${esc(p.name)} · ${p.age} 岁</strong><small>${SPECIALTIES[p.specialty][0]}</small><small>${p.floor===null?'待安排':'B'+p.floor+' · '+esc(state.floors.find(f=>f.id===p.floor).name)}</small><button data-person="${p.id}">查看档案</button></div></div>`).join('')}</div>`,'directory');}
function personModal(id){const p=state.people.find(p=>p.id===id);if(!p)return;wardrobePerson=id;showModal('居民档案',`<div class="wardrobe"><div class="wardrobe-preview" id="wardrobePreview">${character(p)}</div><div><label class="input-label" for="personName">名字</label><div class="input-row"><input id="personName" maxlength="20" value="${esc(p.name)}"><button data-save-name="${p.id}">保存</button></div><div class="stat"><span>年龄</span><strong>${p.age} 岁</strong></div><div class="stat"><span>特长</span><strong>${SPECIALTIES[p.specialty][0]}</strong></div><p class="note">${SPECIALTIES[p.specialty][1]}</p><div class="stat"><span>所在楼层</span><strong>${p.floor===null?'待安排':'B'+p.floor}</strong></div><button class="secondary" data-work-person="${p.id}">安排工作</button></div></div><div class="wardrobe" style="margin-top:15px"><div><p class="note">可自由选择部件。新居民随机搭配，外观会随存档保存。</p><button class="secondary" data-random-look="${p.id}">↻ 随机一套搭配</button></div><div>${['head','top','bottom'].map((k,i)=>`<label class="input-label" for="look-${k}">${['头部与发型','上半身','下半身与鞋子'][i]}</label><select id="look-${k}" data-look="${k}">${Array.from({length:16},(_,j)=>`<option value="${j}" ${p.look[k]===j?'selected':''}>${i===0?'发型':j<8?'明亮色系':'低调色系'} · ${j+1} 号</option>`).join('')}</select>`).join('')}</div></div>`,'person');}
function guide(){showModal('欢迎回家，经营者',`<div class="dialog-guide"><p>这里有 12 种房间、5 类楼层，还有等待安顿的居民。</p><ol><li><b>安排居民：</b>点击房间 → 安排居民。每人贡献一份收入；特长与房间类别匹配时，个人收入增加 25%。年龄用于人物档案，不影响收益。</li><li><b>金币自动结算：</b>按分钟计收支，每秒更新。运行楼层有固定维护费；空房间也扣费，暂停后停止收支。金币最低为 0。</li><li><b>建造楼层：</b>选择用途、支付金币，等待 0–5 分钟。容量为 2–5 人，房间可以重复建造。</li><li><b>电梯接送：</b>在大厅接到访客，再点击他指定楼层的电梯。获得 25 金币，有空床位时访客会入住，并在目标层有位置时直接留在该层。未入住的访客会在目标层停留 60 秒，满员时在楼层入口候场。宿舍决定整个社区的床位上限。</li><li><b>查看档案：</b>居民都有名字、年龄、特长，头部和衣服可自由搭配。点击档案还可以改名。</li></ol><p>关闭网页后仍结算最多 8 小时的净收支，建造倒计时持续推进。当前浏览器自动存档，可在 ⚙ 中导出、导入。</p></div><button class="primary" id="closeGuide">开始经营</button>`,'help');}
function settings(){showModal('存档与设置',`<p class="dialog-guide">进度保存在当前浏览器。换设备或清理浏览器前，请先导出存档。${saveFailed?'当前保存失败，请立即导出。':''}</p><button class="primary" id="export">导出游戏存档</button><label class="secondary" style="display:block;text-align:center;cursor:pointer">导入游戏存档<input type="file" id="import" accept=".json" hidden></label><button class="secondary danger" id="reset">重新开始</button><p class="note">末日纵深 · 社区经营版<br>玩家属性：金币数。房间基础数据按分钟计算。<br>本版本会自动迁移旧版的金币、居民与楼层。</p>`,'settings');}
function commit(){tasks();save();renderAll();}
function board(id){const v=state.visitors.find(v=>v.id===id);if(!v)return;riding=id;state.lift=0;renderFloors();renderPeople();toast(`已接到 ${v.name}，请点击 B${v.destination} 电梯`);$('floor-'+v.destination).scrollIntoView({behavior:'smooth',block:'nearest'});}
function takeLift(id){const f=state.floors.find(f=>f.id===id);if(id!==0&&(!f||f.readyAt>Date.now())){toast('楼层仍在建造，请稍后再来');return;}state.lift=id;if(riding){const v=state.visitors.find(p=>p.id===riding);if(id===v.destination){const result=E.deliver(state,riding,id);if(result.ok){riding=null;toast(`接送完成！+25 金币 · ${result.joined?result.person.name+' 已入住':'床位已满，访客暂未入住'}`);}else toast(result.reason);}else toast(`访客想去 B${v.destination}，请继续接送`);}commit();}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-room]');if(!b||b.disabled)return;const d=b.dataset;
 if(d.room){selected=Number(d.room);renderFloors();renderDetails();}
 else if(d.lift)takeLift(Number(d.lift));
 else if(d.ride)board(Number(d.ride));
 else if(d.category)buildModal(d.category);
 else if(d.build){const result=E.build(state,d.build);if(!result.ok){toast(result.reason);return;}selected=result.floor.id;closeModal();commit();toast(result.floor.buildSeconds?'已支付 '+result.floor.buildCost+' 金币，开始建造':'楼层立即建成');setTimeout(()=>$('floor-'+selected).scrollIntoView({behavior:'smooth',block:'nearest'}),20);}
 else if(d.assign){const [id,dest]=d.assign.split(':').map(Number),result=E.assign(state,id,dest||null);if(!result.ok){toast(result.reason);return;}closeModal();commit();toast('居民分工已更新');}
 else if(d.person)personModal(Number(d.person));
 else if(d.workPerson)assignModal(Number(d.workPerson));
 else if(d.saveName){const p=state.people.find(p=>p.id===Number(d.saveName)),n=$('personName').value.trim();if(!n){toast('名字不能为空');return;}p.name=n.slice(0,20);save();renderPeople();renderFloors();renderSidebar();toast('名字已保存');}
 else if(d.randomLook){const p=state.people.find(p=>p.id===Number(d.randomLook));p.look={head:Math.floor(Math.random()*16),top:Math.floor(Math.random()*16),bottom:Math.floor(Math.random()*16)};save();renderFloors();renderPeople();personModal(p.id);}
 else switch(b.id){case 'build':case 'dig':buildModal();break;case 'directory':case 'allResidents':directory();break;case 'groundLift':takeLift(0);break;case 'assignRoom':assignModal();break;case 'toggleRoom':E.toggle(state,selected);commit();break;case 'help':guide();break;case 'settings':settings();break;case 'closeModal':case 'closeGuide':closeModal();break;case 'renameRoom':{const f=state.floors.find(f=>f.id===selected);showModal('修改楼层名称',`<label class="input-label" for="roomName">B${f.level} · ${ROOMS[f.type].name}</label><div class="input-row"><input id="roomName" maxlength="20" value="${esc(f.name)}"><button id="saveRoomName">保存名称</button></div><p class="note">修改名称不会改变房间类型或属性。</p>`,'rename');break;}case 'saveRoomName':{const n=$('roomName').value.trim();if(!n){toast('名称不能为空');return;}state.floors.find(f=>f.id===selected).name=n.slice(0,20);closeModal();commit();break;}case 'export':{E.settle(state);save();if(window.AndroidBridge?.exportSave){window.AndroidBridge.exportSave(JSON.stringify(state,null,2));toast('请选择存档保存位置');break;}const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='末日纵深存档.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('存档已导出');break;}case 'reset':showModal('重新开始？','<p class="dialog-guide">这会覆盖当前社区进度。建议先导出存档。</p><button class="primary" id="confirmReset">确认重新开始</button>','reset');break;case 'confirmReset':state=E.fresh();selected=2;riding=null;justCompleted.clear();state.floors.forEach(f=>justCompleted.add(f.id));closeModal();commit();guide();break;}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-room]')){e.preventDefault();e.target.click();}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.look){const p=state.people.find(p=>p.id===wardrobePerson);p.look[t.dataset.look]=Number(t.value);$('wardrobePreview').innerHTML=character(p);save();renderFloors();renderPeople();}else if(t.id==='import'&&t.files[0]){try{if(t.files[0].size>1000000)throw Error();let s=JSON.parse(await t.files[0].text());if(s.version===1)s=E.migrate(s);if(!E.validate(s))throw Error();if(s.lastTick>Date.now())s.lastTick=Date.now();state=s;selected=state.floors[0].id;riding=null;justCompleted.clear();state.floors.filter(f=>f.readyAt<=Date.now()).forEach(f=>justCompleted.add(f.id));E.settle(state);closeModal();commit();toast('存档导入成功');}catch{toast('存档无效，请选择本游戏导出的 JSON 文件');}}});
$('dialog').addEventListener('click',e=>{if(e.target===$('dialog'))closeModal();});$('dialog').addEventListener('close',()=>{modalKind='';});
function tick(){E.settle(state);let changed=E.pruneVisits(state);changed=E.arrival(state)||changed;for(const f of state.floors)if(f.readyAt<=Date.now()&&!justCompleted.has(f.id)){justCompleted.add(f.id);E.log(state,`B${f.level} ${f.name} 建造完成。`);toast(f.name+' 已建成，可以安排居民了');changed=true;}changed=tasks()||changed;if(changed)renderAll();else{header();updateTimers();updateDetailRates();}if(modalKind==='build'){for(const b of $('dialogBody').querySelectorAll('[data-build]'))b.disabled=state.coins<ROOMS[b.dataset.build].cost||state.floors.length>=30;}save();}
renderAll();tick();setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();else{E.settle(state);save();}});window.addEventListener('pagehide',()=>{E.settle(state);save();});
let seen=false;try{seen=!!localStorage.getItem('last-light-v2-guide');localStorage.setItem('last-light-v2-guide','1');}catch{}if(!seen)guide();if(initialSettlement.offline>60000)toast('欢迎回家，已结算离线净收支 '+signed(initialSettlement.earned)+' 金币');else if(migrated)toast('旧版进度已保留，并升级为新的社区经营规则');else if(recovered)toast('旧存档无法读取，已开启新的社区');
